# -*- coding: utf-8 -*-
"""MANAPRINT - Generateur LA JOIE (A4 portrait, 16 cartons/feuille).

REGLE ABSOLUE : le decor plus bas EST la planche de Maeva, relevee au trait
   sur sa nouvelle maquette LA JOIE (le cadre, << N deg ___ >>, le titre
   << LA JOIE >> avec ses rayons, la fleur de tiare, les colonnes I . G . O
   avec leurs plages 16-30 / 46-60 / 61-75, les CINQ cases en escalier et
   << La chance en toute joie ! >>). RIEN n'a ete redessine : on ECRIT
   seulement les 5 numeros et le numero de serie.

LA REGLE DU JEU (inchangee) : CINQ numeros en escalier -
   I 16-30 (1 case) . G 46-60 (2 cases triees) . O 61-75 (2 cases triees).
   Le crieur sort 16-30 et 46-75 (le 1-15 et le 31-45 n'existent pas).

L'ARC-EN-CIEL EST CARTON PAR CARTON. En N&B au gris #555555.
"""
import io
import random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

